UPDATE public.profiles SET
  username = 'anas-abara-architecture',
  full_name = 'ANAS ABARA ARCHITECTURE',
  profession = 'Architecte',
  location = 'Tétouan',
  bio = 'مكتب هندسة معمارية، تصميم داخلي والتخطيط العمراني Cabinet d''architecture, design d''intérieur et paysage Architecture, Interior Design, and Landscape Studio',
