INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions) VALUES ('075f377d-c7c0-5d13-8042-e285e96fc295'::uuid, 'eba2a059-acce-56e1-9e7c-66537840ce6a'::uuid, 'Installation de revêtement mural — sur devis', 'Mission de professionnels BTP portée par Castlewood, basé à 10 rue Zyad ibnou rifai étage 3 droite maarif c\\ apes consulting Casablanca. Castle Wood est une entreprise marocaine spécialisée dans l’aménagement intérieur sous toutes ses formes, avec une expérience terrain de 25 ans. Elle propose des solutions globales et personnalisées englobant la conception, la fabrication et la réalisation d’équipements intérieurs pour les habitations, les bureaux, ainsi que les espaces commerciaux et professionnels. Son champ d’intervention inclut les cuisines équipées, les placards, les dressings, les meubles de salle de bain, ainsi que des ments sur….

La mission couvre typiquement les volets réalisation, accompagnement : prestation Installation de revêtement mural, conseil et chiffrage sur devis, intervention selon le périmètre convenu, suivi jusqu''à livraison de la mission. Castlewood intervient dans plusieurs villes (Benslimane, Casablanca, El Jadida…), avec déplacement possible, pour particuliers et entreprises, en mission nationale. Le tarif est établi sur devis, selon l''échelle et les phases confiées.', 'Second œuvre / Finitions', 'https://tachrone-profile-cover-images-pro.s3.eu-west-3.amazonaws.com/file-1505.jpeg', '["https://tachrone-profile-cover-images-pro.s3.eu-west-3.amazonaws.com/file-1331.png", "https://tachrone-profile-cover-images-pro.s3.eu-west-3.amazonaws.com/file-1332.png", "https://tachrone-profile-cover-images-pro.s3.eu-west-3.amazonaws.com/file-1333.png", "https://tachrone-profile-cover-images-pro.s3.eu-west-3.amazonaws.com/file-1334.png", "https://tachrone-profile-cover-images-pro.s3.eu-west-3.amazonaws.com/file-1337.png", "https://tachrone-profile-cover-images-pro.s3.eu-west-3.amazonaws.com/file-1338.png", "https://tachrone-profile-cover-images-pro.s3.eu-west-3.amazonaws.com/file-1326.png", "https://tachrone-profile-cover-images-pro.s3.eu-west-3.amazonaws.com/file-1327.png"]'::jsonb, '["Réalisation", "Accompagnement"]'::jsonb, '["Prestation Installation de revêtement mural", "Conseil et chiffrage sur devis", "Intervention selon le périmètre convenu", "Suivi jusqu''à livraison de la mission", "Conseil et cadrage de la mission", "Prestation adaptée au périmètre convenu"]'::jsonb, '["Options sur devis"]'::jsonb, 'devis', NULL, NULL, 'villes', '["Benslimane", "Casablanca", "El Jadida", "Larache", "Marrakech", "Rabat", "Tétouan"]'::jsonb, NULL, TRUE, FALSE, '["Particuliers", "Entreprises"]'::jsonb, NULL, '["National"]'::jsonb);
INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions) VALUES ('9b174c4c-ef52-541f-9eeb-777e270f4401'::uuid, '606ae6b8-73cc-56a7-8a76-dbc4e82100ad'::uuid, 'Fourniture de matériaux et solutions chantier', 'AlquiMaroc a été créée pour répondre aux besoins spécifiques des secteurs de la construction, du génie civil, des travaux publics et de l’industrie. AlquiMaroc propose des personnalisés et de qualité, qui se distinguent de ceux de ses concurrents. Depuis sa création, AlquiMaroc privilégie le professionnalisme et la proximité avec ses clients, ce qui lui permet de se distinguer sur des complexes. Grâce à cette approche, l’entreprise jouit de la confiance de ses partenaires et d’une solide….

La mission couvre typiquement les volets fourniture, accompagnement : conseil produit adapté au chantier, devis et disponibilité stock, livraison / retrait, support technique commercial. ALQUIMAROC intervient à Casablanca et Tanger, avec déplacement possible, pour entreprises et collectivités, en mission nationale. Le tarif est établi sur devis, selon l''échelle et les phases confiées.', 'Matériaux & équipements', 'https://alquimaroc.ma/wp-content/uploads/2026/03/2026-03-13-143915_upscayl_3x_ultramix-balanced-4x-768x979.png', '["https://alquimaroc.ma/wp-content/uploads/2026/03/2026-03-13-143915_upscayl_3x_ultramix-balanced-4x-1205x1536.png", "https://alquimaroc.ma/wp-content/uploads/2026/03/2026-03-13-143915_upscayl_3x_ultramix-balanced-4x-803x1024.png", "https://alquimaroc.ma/wp-content/uploads/2026/03/2026-03-13-143915_upscayl_3x_ultramix-balanced-4x-1606x2048.png", "https://alquimaroc.ma/wp-content/uploads/2026/03/2026-03-13-143915_upscayl_3x_ultramix-balanced-4x-235x300.png", "https://alquimaroc.ma/wp-content/uploads/2024/12/image1.png", "https://alquimaroc.ma/wp-content/uploads/2026/03/2026-03-13-143915_upscayl_3x_ultramix-balanced-4x.png", "https://alquimaroc.ma/wp-content/uploads/elementor/thumbs/trans-600x800-1-qxvgs21vk7cq9fgia3j1angovcvn9vuhh76jo1gfuo.png"]'::jsonb, '["Fourniture", "Accompagnement"]'::jsonb, '["Conseil produit adapté au chantier", "Devis et disponibilité stock", "Livraison / retrait", "Support technique commercial", "Devis et disponibilité", "Fourniture / livraison"]'::jsonb, '["Livraison chantier", "Accompagnement poseur", "Gamme décorative"]'::jsonb, 'devis', NULL, NULL, 'villes', '["Casablanca", "Tanger"]'::jsonb, NULL, TRUE, FALSE, '["Entreprises", "Collectivités"]'::jsonb, NULL, '["National"]'::jsonb);
INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions) VALUES ('df1d7096-f64a-5dfb-befa-a2d7f7c296ef'::uuid, 'edc2c7a5-bcb4-56ad-97f1-dfd14849795f'::uuid, 'Construction et rénovation clé en main — villas & riads', 'AGS Groupe réalise des sur mesure, de la conception à la livraison. Nous construisons des villas riads et restaurant alliant solidité et esthétisme. Notre engagement : respecter les normes les plus strictes. Votre vision, notre expertise.

La mission couvre typiquement les volets réalisation, accompagnement : construction neuve villas / programmes, rénovation de riads et villas, coordination multi-corps de métier, finitions artisanales (zellige, tadelakt, menuiserie). AGS GROUPE intervient en région Marrakech-Safi, avec déplacement possible, pour particuliers, promoteurs, entreprises et investisseurs, en mission nationale et internationale. Le tarif est établi sur devis, selon l''échelle et les phases confiées. Un accompagnement à distance est également possible.', 'Entreprise générale', 'https://agsgroupe.com/wp-content/uploads/elementor/thumbs/4-rjofehebiwl71vy5u1e1gqe5xecuc18gcofvfkbiq0.png', '["https://agsgroupe.com/wp-content/uploads/2025/05/Creation-sans-titre-2-738x1024.png", "https://agsgroupe.com/wp-content/uploads/2025/05/2-5-1106x1536.png", "https://agsgroupe.com/wp-content/uploads/2025/05/Creation-sans-titre-2-1475x2048.png", "https://agsgroupe.com/wp-content/uploads/2025/05/21-1106x1536.png", "https://agsgroupe.com/wp-content/uploads/2025/05/2-2-768x1066.png", "https://agsgroupe.com/wp-content/uploads/2025/05/7-2-1106x1536.png", "https://agsgroupe.com/wp-content/uploads/2025/05/10-2-1106x1536.png", "https://agsgroupe.com/wp-content/uploads/2025/05/9-2-1106x1536.png"]'::jsonb, '["Réalisation", "Accompagnement"]'::jsonb, '["Construction neuve villas / programmes", "Rénovation de riads et villas", "Coordination multi-corps de métier", "Finitions artisanales (zellige, tadelakt, menuiserie)", "Reporting chantier et suivi budgétaire", "Chiffrage et préparation de chantier"]'::jsonb, '["Gestion de projet à distance (diaspora / investisseurs étrangers)", "Aménagement paysager extérieur", "Gestion de projet à distance"]'::jsonb, 'from', '4500', NULL, 'region', '["Marrakech"]'::jsonb, 'Marrakech-Safi', TRUE, TRUE, '["Particuliers", "Promoteurs", "Entreprises", "Investisseurs"]'::jsonb, NULL, '["International", "National"]'::jsonb);
INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions) VALUES ('59fd6562-da77-5aeb-aaf2-9fe65feb516d'::uuid, '50631b24-cf44-59f6-a3be-e2febbd21374'::uuid, 'Topographie, relevés et géomètre-expert', 'Mission de maîtrise d''œuvre architecturale portée par GEOMATRIX, basé à QUARTIER ABDELLAH EL GARSIFI N 313 EL HOUDA AGADIR. Maîtrisez chaque détail du terrain avec GEOMATRIX. Experts en ingénierie et topographie à Agadir, nous donnons vie à vos avec précision et innovation. Levés, plans 2D/3D, scanner laser, drones : nous sommes votre partenaire de confiance pour des résultats impeccables.

La mission couvre typiquement les volets étude, accompagnement : tOPOGRAPHIE ET GEODESIE, dOSSIERS TECHNIQUES, scanner 3D et BIM, pVA par drone. GEOMATRIX intervient à Agadir, pour propriétaires et promoteurs, en mission nationale. Le tarif est établi sur devis, selon l''échelle et les phases confiées. Un accompagnement à distance est également possible.', 'Architecture / Ingénierie', 'https://geomatrix.ma/wp-content/uploads/2024/05/geomatrix-noir.png', '[]'::jsonb, '["Étude", "Accompagnement"]'::jsonb, '["TOPOGRAPHIE ET GEODESIE", "DOSSIERS TECHNIQUES", "Scanner 3D et BIM", "PVA par drone", "Av. Abdellah Guerssifi n°313 b, 2eme étage, El Houda Agadir", "Conception générale de l''architecture"]'::jsonb, '["Architecture d''intérieur et agencement", "Gestion de projet à distance (diaspora / investisseurs étrangers)"]'::jsonb, 'devis', NULL, NULL, 'villes', '["Agadir"]'::jsonb, NULL, FALSE, TRUE, '["Propriétaires", "Promoteurs"]'::jsonb, NULL, '["National"]'::jsonb);
