INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions) VALUES ('be9bef06-ea41-535d-a92b-f6065780fd71'::uuid, 'c44f2551-c04f-5ba8-8d68-e343053a37fc'::uuid, 'Nettoyage de chantier — prestation professionnelle', 'Mission de associés au chantier et à l''immobilier portée par pur pro , basé à 144, RUE MOHAMED SMIHA ETG 06 APPT 35. NOUS NOUS ENGAGEONS À OFFRIR DES PRESTATIONS DE HAUTE QUALITÉ POUR ASSURER DES ESPACES PROPRES À VIVRE. QUE VOUS SOYEZ UNE ENTREPRISE, UNE INSTITUTION OU UN PARTICULIER, NOUS PROPOSONS DES SOLUTIONS ADAPTÉES À VOS BESOINS GRÂCE À UNE ÉQUIPE QUALIFIÉE ET DES ÉQUIPEMENTS MODERNES.

