INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions) VALUES ('e10fea83-a38d-5a9c-8a7b-8ebfb737ed91'::uuid, '6922d48a-2c44-561d-ada6-d7d34d6bd508'::uuid, 'Matériel électrique — offre clé en main', 'Fadl Energy est une entreprise marocaine spécialisée dans les solutions d''énergie solaire. Nous proposons des de conception, d''installation et de maintenance de systèmes photovoltaïques et de chauffe-eaux solaires, destinés à réduire la consommation énergétique et à promouvoir l''utilisation d''énergie renouvelable. Notre mission est de rendre l''énergie solaire accessible à tous, en offrant des solutions durables et économiques adaptées aux besoins de chaque client. Nous accompagnons aussi bien les….

La mission couvre typiquement les volets fourniture, accompagnement : avenue Mohammed V, Résidence Sara, Appartement N°4, Hay Elalaouiyine, Témara, message Nom Téléphone, envoyer mon message, energy Solaire. Fadl Energy intervient dans plusieurs villes (Casablanca, Kénitra, Rabat…), avec déplacement possible, pour particuliers, promoteurs et entreprises, en mission nationale. Le tarif est établi sur devis, selon l''échelle et les phases confiées.', 'Matériaux & équipements', 'https://fadlenergy.com/wp-content/uploads/2024/08/high-angle-view-electronic-tools-with-computer-chips-wooden-background-min-scaled.jpg', '["https://fadlenergy.com/wp-content/uploads/2025/02/Capture-decran-2025-02-23-214618-600x185.png", "https://fadlenergy.com/wp-content/uploads/2024/09/Fadl-products-768x488.png", "https://fadlenergy.com/wp-content/uploads/2024/09/Fadl-products-600x381.png", "https://fadlenergy.com/wp-content/uploads/2024/07/Chauffe-eau-solaire-card.png", "https://fadlenergy.com/wp-content/uploads/2024/09/Fadl-products.png", "https://fadlenergy.com/wp-content/uploads/2024/07/man-making-cable-voltage-measure.png", "https://fadlenergy.com/wp-content/uploads/2024/07/american-public-power-association-XGAZzyLzn18-unsplash.png", "https://fadlenergy.com/wp-content/uploads/2025/02/Capture-decran-2025-02-23-214618-300x93.png"]'::jsonb, '["Fourniture", "Accompagnement"]'::jsonb, '["Avenue Mohammed V, Résidence Sara, Appartement N°4, Hay Elalaouiyine, Témara", "Message Nom Téléphone", "Envoyer mon message", "Energy Solaire", "Chauffe eau solaire", "Instalation électrique"]'::jsonb, '["Livraison chantier", "Accompagnement poseur", "Gamme décorative"]'::jsonb, 'devis', NULL, NULL, 'villes', '["Casablanca", "Kénitra", "Rabat", "Salé", "Témara"]'::jsonb, NULL, TRUE, FALSE, '["Particuliers", "Promoteurs", "Entreprises"]'::jsonb, NULL, '["National"]'::jsonb);
