INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions) VALUES ('8950553a-99af-57d3-9e0c-39779a133b8c'::uuid, '06624d8b-d338-52f3-9cc6-7b2a8b844248'::uuid, 'Ferronnerie / Métallurgie — offre clé en main', 'El Manar Tréfilage est votre spécialiste en fil tréfilé, grillage et pointerie en acier doux de haute qualité. Nous proposons des solutions métallurgiques adaptées à divers secteurs industriels. Grâce à notre expertise en tréfilage, nous produisons des fils en acier doux et galvanisé avec une précision et une résistance exceptionnelles, répondant aux besoins spécifiques de nos clients.

