INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions) VALUES ('bd37b53a-2dc6-546c-8c8d-68ed490f5fa9'::uuid, '047fa3c3-0682-5518-ba14-40789a20995d'::uuid, 'Carrelage — offre clé en main', 'Mission de fourniture de matériaux et solutions chantier portée par LEADERPAK, basé à 43, zone industrielle sud-ouest Mohammedia. Fondée en 2013, LEADER PAK s''est imposée comme une référence incontournable grâce à son expertise, son engagement envers la qualité et son innovation constante. Sous la marque VIDAL, l’entreprise développe et commercialise une gamme complète de produits plastiques destinés à la construction, et plus particulièrement pour la pose de carrelage : les clips de nivellement, les cales, les croisillons d''espacement, et les pinces de serrage. Les produits VIDAL sont le résultat d''une coopération et d''une intégration….

La mission couvre typiquement les volets fourniture, accompagnement : nos Produits, cales de nivellement, clips de nivellement de carrelage, croisillons de nivellement. LEADERPAK intervient à Casablanca, pour particuliers et entreprises, en mission nationale. Le tarif est établi sur devis, selon l''échelle et les phases confiées.', 'Matériaux & équipements', 'https://vidaltools.ma/wp-content/uploads/2025/01/VIDAL-Default-Social-Share-Image.png', '["https://vidaltools.ma/wp-content/uploads/2026/03/ENTRETOISE-VIDAL-1-768x768.webp", "https://vidaltools.ma/wp-content/uploads/2025/02/produits-vidal-tools-1-768x768.webp", "https://vidaltools.ma/wp-content/uploads/2025/02/produits-vidal-tools-3-768x768.webp", "https://vidaltools.ma/wp-content/uploads/2025/06/tile-levelling-system-1-600x730.webp", "https://vidaltools.ma/wp-content/uploads/2025/06/tile-levelling-system-4-600x730.webp", "https://vidaltools.ma/wp-content/uploads/2025/03/nivellement-de-carrelage-1024x683.webp", "https://vidaltools.ma/wp-content/uploads/2025/03/nivellement-de-carrelage-600x400.webp", "https://vidaltools.ma/wp-content/uploads/2025/02/produits-vidal-tools-4-768x768.webp"]'::jsonb, '["Fourniture", "Accompagnement"]'::jsonb, '["Nos Produits", "Cales de nivellement", "Clips de nivellement de carrelage", "Croisillons de nivellement", "Entretoises de Carrelage", "Pince de nivellement"]'::jsonb, '["Livraison chantier", "Accompagnement poseur", "Gamme décorative"]'::jsonb, 'devis', NULL, NULL, 'villes', '["Casablanca"]'::jsonb, NULL, FALSE, FALSE, '["Particuliers", "Entreprises"]'::jsonb, NULL, '["National"]'::jsonb);
