INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions) VALUES ('2960ca3f-7f60-5353-b330-2229f8543c90'::uuid, 'ff742c20-0951-5af2-a8d6-b9429bcc781e'::uuid, 'Travaux et réalisation de chantier', 'BECOMAR est une entreprise marocaine spécialisée dans la production et la commercialisation de solutions béton innovantes et de qualité supérieure. Fondée pour répondre aux besoins croissants du marché de la construction, elle s''appuie sur une expertise technique pointue et des moyens de production modernes pour offrir à ses clients des produits fiables et durables. L’offre de BECOMAR couvre une large gamme de produits en béton préfabriqué, allant des agglos, poutrelles et hourdis certifiés aux normes marocaines,….

La mission couvre typiquement les volets réalisation, accompagnement : nos sur mesure pour la construction, commercialisation, construction, 25 ans d''excellence dans la fabrication de produits en béton. BECOMAR intervient au Maroc, avec déplacement possible, pour entreprises et architectes / bureaux d''études, en mission nationale. Le tarif est établi sur devis, selon l''échelle et les phases confiées. Un accompagnement à distance est également possible.', 'Matériaux & équipements', 'https://irp.cdn-website.com/62bdc277/dms3rep/multi/opt/fond-architecture-inspiration-brutaliste_23-2149162852-601w.jpg', '["https://irp.cdn-website.com/62bdc277/dms3rep/multi/opt/_52A9975-602w.jpg", "https://irp.cdn-website.com/62bdc277/dms3rep/multi/opt/2150576453-792h.webp"]'::jsonb, '["Réalisation", "Accompagnement"]'::jsonb, '["Nos services sur mesure pour la construction", "Commercialisation", "Construction", "25 ans d''excellence dans la fabrication de produits en béton", "Nos certifications de qualité", "ISO 9001 : Système de management de la qualité"]'::jsonb, '["Gestion de projet à distance", "Rénovation / réhabilitation", "Aménagements extérieurs", "Gestion de projet à distance (diaspora / investisseurs étrangers)"]'::jsonb, 'devis', NULL, NULL, 'maroc', '["Berrechid", "Casablanca", "El Jadida", "Fès", "Kénitra", "Marrakech", "Meknès", "Mohammedia", "Rabat", "Safi", "Salé", "Settat", "Skhirat", "Tanger", "Témara", "Tétouan"]'::jsonb, 'Maroc', TRUE, TRUE, '["Entreprises", "Architectes / Bureaux d''études"]'::jsonb, NULL, '["National"]'::jsonb);
