INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions) VALUES ('d7c5a5dc-b17b-5167-b2d5-b2587c69c49b'::uuid, '20f5c30e-2946-5b1a-9dba-2c5fc5893e84'::uuid, 'Laboratoire — offre clé en main', 'Mission de maîtrise d''œuvre architecturale portée par TRECQ, basé à Z.I sidi slimane - lot 75/77 moul elkifane. Avec 25 ans d’expérience, TRECQ est un laboratoire de référence au Maroc, spécialisé dans le contrôle de la qualité des matériaux, les études géotechniques, et le suivi technique des de construction et d’infrastructures. Nous proposons des prestations couvrant tout le territoire marocain, avec : Une expertise confirmée en essais de sols, bétons, enrobés et granulats, Des équipements de pointe certifiés aux normes marocaines (NM) et internationales (ASTM, EN, ISO), Une équipe pluridisciplinaire composée….

La mission couvre typiquement les volets étude, accompagnement : expertises de laboratoire EL, reconnaissances, réalisez vos en pleine confiance, nos activités. TRECQ intervient au Maroc, avec déplacement possible, pour entreprises et collectivités, en mission nationale et internationale. Le tarif est établi sur devis, selon l''échelle et les phases confiées.', 'Architecture / Ingénierie', 'http://trecq.ma/gallery_gen/bfcf44b97b6437ded199bccbc56cb6c9_960x960_240x0_1440x960_crop.jpg?ts=1758629015', '["http://trecq.ma/gallery_gen/0f2745659186dbe23dc5d7d5d9c398f8_1906x1471_776x0_3269x1471_crop.jpg?ts=1758629015", "http://trecq.ma/gallery_gen/51fb58c551a73cd8a3f114949e3aa418_800x763_104x0_1018x764_crop.jpg?ts=1758629015", "http://trecq.ma/gallery_gen/c9361ed40ceaca8fc4d961f7685c5ba9_700x88_fit.jpg?ts=1758629015", "http://trecq.ma/gallery_gen/5bbb75726f62216badfe344e0ffc8521_fit.PNG?ts=1758629015", "http://trecq.ma/gallery_gen/db6804be4cf1e4c92e99660f4be67449_80x80_fit.png?ts=1758629015", "http://trecq.ma/gallery_gen/f3757e59c31a645758b9130568a74a0b_80x80_fit.png?ts=1758629015", "http://trecq.ma/gallery_gen/1272c9472957eb3207c53d2cab51fa03_80x80_fit.png?ts=1758629015", "http://trecq.ma/gallery_gen/996ab977f167faaa051c6d745e74aa19_800x818_219x0_1232x818_crop.jpg?ts=1758629015"]'::jsonb, '["Étude", "Accompagnement"]'::jsonb, '["Expertises de laboratoire EL", "Reconnaissances", "Réalisez vos projets en pleine confiance", "Nos activités", "Études Géotechniques", "Les études géotechniques comprennent les principales composantes suivantes :"]'::jsonb, '["Architecture d''intérieur et agencement"]'::jsonb, 'devis', NULL, NULL, 'maroc', '["Agadir", "Al Hoceïma", "Berrechid", "Casablanca", "El Jadida", "Errachidia", "Fès", "Ifrane", "Marrakech", "Meknès", "Mohammedia", "Nador", "Tanger", "Taza", "Témara", "Tinghir", "Tiznit"]'::jsonb, 'Maroc', TRUE, FALSE, '["Entreprises", "Collectivités"]'::jsonb, NULL, '["International", "National"]'::jsonb);
INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions) VALUES ('5bda4849-5509-5631-bbef-5fabba950c6c'::uuid, '3d90d8be-2d25-5a6a-8114-37b913fd6fd8'::uuid, 'Fourniture de matériaux et solutions chantier', 'Omari Zellige est un fabricant de carreaux marocains basé à Fès, berceau historique de l’artisanat du zellige. Spécialisée dans la fabrication artisanale de carreaux en terre cuite émaillée, l’entreprise perpétue un savoir-faire ancestral transmis de génération en génération. Chaque carreau est façonné à la main à partir d’argile naturelle de la région, émaillé, cuit au four, puis découpé avec précision, offrant ainsi des pièces uniques au charme authentique. Chez Omari Zellige, la tradition se conjugue avec la….

La mission couvre typiquement les volets fourniture, accompagnement : conseil produit adapté au chantier, devis et disponibilité stock, livraison / retrait, support technique commercial. Omari Zellige intervient à Fès, pour entreprises et architectes / bureaux d''études, en mission nationale et internationale. Le tarif est établi sur devis, selon l''échelle et les phases confiées.', 'Matériaux & équipements', 'https://www.omarizellige.com/HS2.jpg', '["https://www.omarizellige.com/zelb11.jpg", "https://www.omarizellige.com/zelb7.webp", "https://www.omarizellige.com/zelb1.jpg", "https://www.omarizellige.com/zelb8.jpg", "https://www.omarizellige.com/zelb5.jpeg", "https://www.omarizellige.com/zelb6.png", "https://www.omarizellige.com/zelb2.png", "https://www.omarizellige.com/zelb3.png"]'::jsonb, '["Fourniture", "Accompagnement"]'::jsonb, '["Conseil produit adapté au chantier", "Devis et disponibilité stock", "Livraison / retrait", "Support technique commercial", "Devis et disponibilité", "Fourniture / livraison"]'::jsonb, '["Livraison chantier", "Accompagnement poseur", "Gamme décorative"]'::jsonb, 'devis', NULL, NULL, 'villes', '["Fès"]'::jsonb, NULL, FALSE, FALSE, '["Entreprises", "Architectes / Bureaux d''études"]'::jsonb, NULL, '["International", "National"]'::jsonb);
