INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions) VALUES ('4435a8e6-cbf8-5d0a-8bc5-1e263704b01b'::uuid, 'c83df0de-cf2b-5b71-b40c-11d7f849ded3'::uuid, 'Fourniture de matériaux et solutions chantier', 'Synergy Solutions est une entreprise spécialisée en énergie solaire photovoltaïque, créée en 2021 par des experts en énergies renouvelables. Nous avons déjà installé plus de 1 MégaWatt d’énergie solaire à travers une multitude de réalisés partout au Maroc. Nous accompagnons nos clients depuis la conception, l’étude et l’ingénierie, en passant par la réalisation et le service après-vente, jusqu’à la maintenance. Nos prestations s’adressent aux secteurs résidentiel (villas), industriel, agricole, hôtelier….

La mission couvre typiquement les volets fourniture, accompagnement : conseil produit adapté au chantier, devis et disponibilité stock, livraison / retrait, support technique commercial. Synergy Solutions intervient au Maroc, avec déplacement possible, pour particuliers et entreprises, en mission nationale. Le tarif est établi sur devis, selon l''échelle et les phases confiées.', 'Matériaux & équipements', 'https://i.imgur.com/xA8aaXN.png', '[]'::jsonb, '["Fourniture", "Accompagnement"]'::jsonb, '["Conseil produit adapté au chantier", "Devis et disponibilité stock", "Livraison / retrait", "Support technique commercial", "Devis et disponibilité", "Fourniture / livraison"]'::jsonb, '["Livraison chantier", "Accompagnement poseur", "Gamme décorative"]'::jsonb, 'devis', NULL, NULL, 'maroc', '["Agadir", "Casablanca"]'::jsonb, 'Maroc', TRUE, FALSE, '["Particuliers", "Entreprises"]'::jsonb, NULL, '["National"]'::jsonb);
INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions) VALUES ('14723ba4-5251-54b0-ab0a-db53f7d358bd'::uuid, 'eeea4c89-6318-59d8-88bd-f9f5391ac809'::uuid, 'Travaux et réalisation de chantier', 'Benapro est une entreprise de construction marocaine proposant des fiables en construction, rénovation et finition. Nous visons l''excellence, privilégiant un savoir-faire de qualité, une communication transparente et la réalisation de dans les délais et le budget impartis. Notre équipe de professionnels expérimentés veille à la perfection de chaque détail, transformant votre vision en réalité.

La mission couvre typiquement les volets réalisation, accompagnement : étude de faisabilité / chiffrage, exécution des travaux, coordination des corps de métier, réception et levée de réserves. Benapro intervient à Marrakech, pour entreprises, en mission nationale. Le tarif est établi sur devis, selon l''échelle et les phases confiées. Un accompagnement à distance est également possible.', 'Construction Gros Oeuvre', 'https://tachrone-profile-cover-images-pro.s3.eu-west-3.amazonaws.com/file-4345.png', '["https://tachrone-profile-cover-images-pro.s3.eu-west-3.amazonaws.com/file-4346.png", "https://tachrone-profile-cover-images-pro.s3.eu-west-3.amazonaws.com/file-4347.png", "https://tachrone-profile-cover-images-pro.s3.eu-west-3.amazonaws.com/file-4348.png", "https://tachrone-profile-cover-images-pro.s3.eu-west-3.amazonaws.com/file-4349.png", "https://tachrone-profile-cover-images-pro.s3.eu-west-3.amazonaws.com/file-4555.png", "https://tachrone-profile-cover-images-pro.s3.eu-west-3.amazonaws.com/file-4875.jpg", "https://tachrone-profile-cover-images-pro.s3.eu-west-3.amazonaws.com/file-4876.jpg", "https://tachrone-profile-cover-images-pro.s3.eu-west-3.amazonaws.com/file-4877.jpg"]'::jsonb, '["Réalisation", "Accompagnement"]'::jsonb, '["Étude de faisabilité / chiffrage", "Exécution des travaux", "Coordination des corps de métier", "Réception et levée de réserves", "Chiffrage et préparation de chantier"]'::jsonb, '["Gestion de projet à distance", "Rénovation / réhabilitation", "Aménagements extérieurs", "Gestion de projet à distance (diaspora / investisseurs étrangers)"]'::jsonb, 'devis', NULL, NULL, 'villes', '["Marrakech"]'::jsonb, NULL, FALSE, TRUE, '["Entreprises"]'::jsonb, NULL, '["National"]'::jsonb);
