INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions) VALUES ('45ba42c3-7f0a-5277-9cbc-2e06e6d2af86'::uuid, '8699ffac-86b9-587b-99bd-ddc9632dcc82'::uuid, 'Pose de vitres — étude, fourniture et pose', 'Mission de pose et installation portée par Vitres Intelligentes Maroc, basé à IMM 7, RUE MOULAY RACHID, APPT N 10, 4 EME ETAGE, HASSAN RABAT. Grâce à Vitres Intelligentes Maroc, passez de la transparence à l’intimité en un instant. Offrez à vos espaces élégance, confort et innovation. Nos films de verre intelligents redéfinissent vos environnements professionnels : bureaux, hôtels, hôpitaux, salles de réunion ou espaces publics. Sans travaux lourds, vous choisissez entre ouverture totale sur la lumière ou bulle d’intimité, d’un simple geste. Notre équipe accompagne chaque projet de bout en bout — du conseil technique à l’installation certifiée,….

La mission couvre typiquement les volets réalisation, accompagnement : prestation Pose de vitres, conseil et chiffrage sur devis, intervention selon le périmètre convenu, suivi jusqu''à livraison de la mission. Vitres Intelligentes Maroc intervient à Casablanca et Rabat, avec déplacement possible, pour entreprises et collectivités, en mission nationale. Le tarif est établi sur devis, selon l''échelle et les phases confiées.', 'Second œuvre / Finitions', 'https://vitres-intelligentes.com/og-image.jpg', '[]'::jsonb, '["Réalisation", "Accompagnement"]'::jsonb, '["Prestation Pose de vitres", "Conseil et chiffrage sur devis", "Intervention selon le périmètre convenu", "Suivi jusqu''à livraison de la mission", "Étude et prise de cotes", "Fabrication / fourniture"]'::jsonb, '["Options de finition"]'::jsonb, 'devis', NULL, NULL, 'villes', '["Casablanca", "Rabat"]'::jsonb, NULL, TRUE, FALSE, '["Entreprises", "Collectivités"]'::jsonb, NULL, '["National"]'::jsonb);
INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions) VALUES ('704dfc67-bfc3-5940-b3b1-7756688dfa29'::uuid, '6c5642e6-2797-5790-b4a8-803e86022929'::uuid, 'Travaux et réalisation de chantier', 'POINT TP est une société d’aménagement intérieur et extérieur et de rénovation qui concerne des travaux qui touchent à la structure , la restauration et la remise en état des bâtis dans leur état original, en respectant les logiques de construction, ou de réhabilitation qui consiste à faire du neuf à partir de l’ancien.

La mission couvre typiquement les volets réalisation, accompagnement : nos réalisations, nous construisons jusqu’au bout de vos rêves, qui sommes nous, restauration. POINT TP intervient à Casablanca et Tanger, avec déplacement possible, pour entreprises, en mission nationale. Le tarif est établi sur devis, selon l''échelle et les phases confiées.', 'Construction Gros Oeuvre', 'https://pointtp.ma/wp-content/uploads/2023/05/IMG-20230509-WA0004-768x1047.jpg', '["https://pointtp.ma/wp-content/uploads/2023/05/IMG-20230509-WA0001-769x1024.jpg", "https://pointtp.ma/wp-content/uploads/2023/05/IMG-20230509-WA0003-768x1023.jpg", "https://pointtp.ma/wp-content/uploads/2023/05/IMG-20230509-WA0005-768x577.jpg", "https://pointtp.ma/wp-content/uploads/2023/05/IMG-20230509-WA0001-768x1023.jpg", "https://pointtp.ma/wp-content/uploads/2023/05/IMG-20230509-WA0003-1-769x1024.jpg", "https://pointtp.ma/wp-content/uploads/2023/05/IMG-20230509-WA0005-1024x769.jpg", "https://pointtp.ma/wp-content/uploads/2023/05/IMG-20230509-WA0002-769x1024.jpg", "https://pointtp.ma/wp-content/uploads/2023/05/IMG-20230509-WA0003-769x1024.jpg"]'::jsonb, '["Réalisation", "Accompagnement"]'::jsonb, '["Nos réalisations", "Nous construisons jusqu’au bout de vos rêves", "Qui sommes nous", "Restauration", "Rehabilitation", "Construction"]'::jsonb, '["Gestion de projet à distance", "Rénovation / réhabilitation", "Aménagements extérieurs", "Aménagement paysager extérieur"]'::jsonb, 'devis', NULL, NULL, 'villes', '["Casablanca", "Tanger"]'::jsonb, NULL, TRUE, FALSE, '["Entreprises"]'::jsonb, NULL, '["National"]'::jsonb);
INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions) VALUES ('4cf68903-975a-57a3-93f3-135f7e3654cc'::uuid, '03d23db6-7243-5512-84ba-f66967d5808e'::uuid, 'Études techniques BTP — conception et suivi', 'Sterixis Engineering – Solid Foundations, Smart Solutions Bureau d’études pluridisciplinaire en ingénierie du bâtiment et des infrastructures. Nous réalisons études, diagnostics, modélisation BIM, calculs de structure, suivi de travaux, audits énergétiques et assistance à maîtrise d’ouvrage. Des solutions techniques fiables, durables et adaptées à chaque projet.

La mission couvre typiquement les volets étude, accompagnement : conception architecturale, dossiers administratifs / permis, coordination des intervenants, suivi de chantier. Sterixis Engineering (Bureau d’études techniques) intervient au Maroc, avec déplacement possible, pour particuliers et entreprises, en mission nationale. Le tarif est établi sur devis, selon l''échelle et les phases confiées.', 'Architecture / Ingénierie', 'https://taplink.st/a/e/0/f/1/d3e650.png?2', '["https://taplink.at/s/i/taplink-opengraph.jpg", "https://taplink.st/p/1/4/7/5/26531025.png?0", "https://taplink.st/p/d/7/2/6/27971697.png?0", "https://taplink.st/p/4/6/d/6/28216096.jpg?0", "https://taplink.st/p/0/f/0/8/27507243.jpg?0", "https://taplink.st/p/5/c/b/0/27971670.png?0", "https://taplink.st/p/2/d/c/0/26510187.png?0", "https://taplink.st/p/c/7/f/0/27507177.jpg?0"]'::jsonb, '["Étude", "Accompagnement"]'::jsonb, '["Conception architecturale", "Dossiers administratifs / permis", "Coordination des intervenants", "Suivi de chantier", "Conception générale de l''architecture", "Dossiers administratifs et permis"]'::jsonb, '["Architecture d''intérieur et agencement"]'::jsonb, 'devis', NULL, NULL, 'maroc', '["Agadir", "Al Hoceïma", "Azilal", "Benslimane", "Berrechid", "Dakhla", "El Jadida", "Errachidia", "Fès", "Ifrane", "Kénitra", "Khouribga", "Marrakech", "Martil", "Meknès", "Mohammedia", "Nador", "Rabat", "Safi", "Salé", "Settat", "Tanger", "Tétouan"]'::jsonb, 'Maroc', TRUE, FALSE, '["Particuliers", "Entreprises"]'::jsonb, NULL, '["National"]'::jsonb);
