INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions) VALUES ('80a588c1-3bde-5e03-8825-8131b59bda62'::uuid, '6eaffd4d-fac0-5f44-b5bc-c149acc27cca'::uuid, 'Laboratoire — offre clé en main', 'Mission de maîtrise d''œuvre architecturale portée par LEGBTP, basé à 38 rue 1 lot scimie ain chok. Depuis sa création en 2007, LEGBTP se veut être un laboratoire géotechnique leader dans le domaine du BTP au Maroc. En effet, il a développé son champ d’activités au fur et à mesure de son évolution. Celui-ci englobe actuellement les études géotechniques dans leur sens le plus large, conformément à la norme NF P 94-500, les études hydrologiques, hydrogéologiques et géophysiques, les expertises géotechniques et structurelles, ainsi que le contrôle de la qualité des travaux et des matériaux de construction.

La mission couvre typiquement les volets étude, accompagnement : eXPERTISES TECHNIQUES, cONTRÔLE DE LA QUALITÉ, éTUDES GÉOPHYSIQUES, certifications. LEGBTP intervient à Casablanca, pour particuliers et entreprises, en mission nationale. Le tarif est établi sur devis, selon l''échelle et les phases confiées.', 'Architecture / Ingénierie', 'https://legbtp.ma/wp-content/uploads/2023/03/DSC04355-768x513.jpg', '["https://legbtp.ma/wp-content/uploads/2023/03/DSC04355-1024x684.jpg", "https://legbtp.ma/wp-content/uploads/2023/03/IMG_9006-800x715.jpg", "https://legbtp.ma/wp-content/uploads/2023/02/IMG_8165-1024x683.jpg", "https://legbtp.ma/wp-content/uploads/2023/02/IMG_8165-768x512.jpg", "https://legbtp.ma/wp-content/uploads/2023/02/IMG_8165-1536x1024.jpg", "https://legbtp.ma/wp-content/uploads/2023/02/IMG_8165-2048x1365.jpg", "https://legbtp.ma/wp-content/uploads/2023/03/Photo-1-768x512.jpg", "https://legbtp.ma/wp-content/uploads/2023/03/Photo-1-1024x683.jpg"]'::jsonb, '["Étude", "Accompagnement"]'::jsonb, '["EXPERTISES TECHNIQUES", "CONTRÔLE DE LA QUALITÉ", "ÉTUDES GÉOPHYSIQUES", "Certifications", "Qualification du ministère de l’équipement", "Accréditation NM-ISO-17025"]'::jsonb, '["Architecture d''intérieur et agencement"]'::jsonb, 'devis', NULL, NULL, 'villes', '["Casablanca"]'::jsonb, NULL, FALSE, FALSE, '["Particuliers", "Entreprises"]'::jsonb, NULL, '["National"]'::jsonb);
INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions) VALUES ('780724dc-5ebd-51df-8c63-1727661282e1'::uuid, '6d1760c8-a3d9-5b87-be74-7f49755b315e'::uuid, 'Installation électrique — offre clé en main', 'GENELTEC – Électricité & Smart Home Solutions GENELTEC est une entreprise marocaine spécialisée dans les installations électriques complètes pour villas, bâtiments résidentiels et commerciaux. Nous offrons des solutions modernes et intelligentes pour rendre chaque espace plus sûr, plus efficace et plus confortable. Nos domaines d’expertise : Électricité du bâtiment et industrielle – Installation, rénovation et maintenance complètes Smart Home – Commande intelligente de l’éclairage, volets, climatisation,….

La mission couvre typiquement les volets réalisation, accompagnement : études électriques, fourniture, pose et mise en service, conformité NF C 15-100 · IEC sur chaque chantier, partenaires premium : Schneider, ABB, Legrand, Siemens, maintenance préventive et corrective 24/7. Geneltec intervient au Maroc, avec déplacement possible, pour particuliers, s immobilières, promoteurs, entreprises et architectes / bureaux d''études, en mission nationale. Le tarif est établi sur devis, selon l''échelle et les phases confiées. Un accompagnement à distance est également possible.', 'Second œuvre / Finitions', 'https://www.geneltec.ma/assets/og.webp', '["https://hfkygmwvofuffabyfeyk.supabase.co/storage/v1/object/public/partners/1780338631462-gb3bejds24p.jpeg", "https://hfkygmwvofuffabyfeyk.supabase.co/storage/v1/object/public/partners/1780312111846-hgvn4u8jtz.jpeg", "https://hfkygmwvofuffabyfeyk.supabase.co/storage/v1/object/public/partners/1780339392707-a7x8viwb1k.jpeg", "https://hfkygmwvofuffabyfeyk.supabase.co/storage/v1/object/public/partners/1780311570839-k8b4er3x7w.png", "https://hfkygmwvofuffabyfeyk.supabase.co/storage/v1/object/public/partners/1780311744758-fkvh5djrb9.png", "https://hfkygmwvofuffabyfeyk.supabase.co/storage/v1/object/public/partners/1780311873928-4eowy89k9kt.png", "https://hfkygmwvofuffabyfeyk.supabase.co/storage/v1/object/public/partners/1780311625143-h763ozj2vb.png", "https://hfkygmwvofuffabyfeyk.supabase.co/storage/v1/object/public/partners/1780311831564-yqm0u5ta4yg.png"]'::jsonb, '["Réalisation", "Accompagnement"]'::jsonb, '["Études électriques, fourniture, pose et mise en service", "Conformité NF C 15-100 · IEC sur chaque chantier", "Partenaires premium : Schneider, ABB, Legrand, Siemens", "Maintenance préventive et corrective 24/7", "Mohammedia, Maroc Siège · Interventions partout au Maroc", "02 Notre approche · Nos services"]'::jsonb, '["Options sur devis", "Gestion de projet à distance (diaspora / investisseurs étrangers)"]'::jsonb, 'devis', NULL, NULL, 'maroc', '["Azemmour", "Berrechid", "Casablanca", "El Jadida", "Kénitra", "Marrakech", "Meknès", "Mohammedia", "Rabat", "Salé", "Settat", "Skhirat", "Témara"]'::jsonb, 'Maroc', TRUE, TRUE, '["Particuliers", "Agences immobilières", "Promoteurs", "Entreprises", "Architectes / Bureaux d''études"]'::jsonb, NULL, '["National"]'::jsonb);
INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions) VALUES ('8a39521f-fa81-587f-962a-658dc386f7eb'::uuid, '0dcd8631-274c-5149-a10b-814c9928fa22'::uuid, 'Pose de cuisine — étude, fourniture et pose', 'Mission de pose et installation portée par Arnoss cuisine, basé à MAGAZIN NO 69 IMM 17 GROUP 3 BASSATINE OULFA Casablanca 20220. Arnoss design est une entreprise spécialisée dans la conception, l''aménagement et la fabrication de meubles de cuisine, dressing et de meubles spécialisés.

