INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions) VALUES ('18501ebc-132f-5da0-9fe0-87defee2670f'::uuid, 'b1f4130d-f0d3-5f87-9267-6e075f99abb7'::uuid, 'Maîtrise d''œuvre architecturale — conception et suivi', 'Studio 33 Architects est un cabinet d’architecture et de design basé au Maroc, spécialisé dans la conception de résidentiels haut de gamme et sur-mesure. Notre approche allie luxe, élégance et fonctionnalité, en mettant l’accent sur la qualité des matériaux, l’harmonie des volumes et l’intégration du bâtiment dans son environnement. Chaque projet est pensé comme une œuvre unique, reflétant à la fois les aspirations de nos clients et notre exigence artistique. Nous proposons un accompagnement complet,….

La mission couvre typiquement les volets étude, accompagnement : conception architecturale, dossiers administratifs / permis, coordination des intervenants, suivi de chantier. Studio 33 architects intervient dans plusieurs villes (Agadir, Casablanca, Dakhla…), avec déplacement possible, pour particuliers et entreprises, en mission nationale. Le tarif est établi sur devis, selon l''échelle et les phases confiées.', 'Architecture / Ingénierie', 'https://tachrone-profile-cover-images-pro.s3.eu-west-3.amazonaws.com/file-6846.png', '["https://tachrone-profile-cover-images-pro.s3.eu-west-3.amazonaws.com/file-6848.png", "https://tachrone-profile-cover-images-pro.s3.eu-west-3.amazonaws.com/file-6849.png", "https://tachrone-profile-cover-images-pro.s3.eu-west-3.amazonaws.com/file-6850.png", "https://tachrone-profile-cover-images-pro.s3.eu-west-3.amazonaws.com/file-1504.jpeg", "https://tachrone-profile-cover-images-pro.s3.eu-west-3.amazonaws.com/file-7846.jpg"]'::jsonb, '["Étude", "Accompagnement"]'::jsonb, '["Conception architecturale", "Dossiers administratifs / permis", "Coordination des intervenants", "Suivi de chantier", "Conception générale de l''architecture", "Dossiers administratifs et permis"]'::jsonb, '["Architecture d''intérieur et agencement", "Aménagement paysager extérieur"]'::jsonb, 'devis', NULL, NULL, 'villes', '["Agadir", "Casablanca", "Dakhla", "El Jadida", "Marrakech"]'::jsonb, NULL, TRUE, FALSE, '["Particuliers", "Entreprises"]'::jsonb, NULL, '["National"]'::jsonb);
INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions) VALUES ('b72c6b90-4714-528e-84df-c129653c113a'::uuid, 'f6701fdf-2bf7-5e5e-92e6-0237f1cc979c'::uuid, 'Infographie 3D / Maquette — offre clé en main', 'Mission de maîtrise d''œuvre architecturale portée par Impair studio, basé à 2eme étage, appt 18 Immeuble F, Bd Gaza, résidence Al Awaile, Témara. Groupe d''architectes et spécialistes dans la création de contenu visuel pour les professionnels. Nous travaillons avec des s d''architecture, des promoteurs immobiliers et maîtres d''ouvrages dans tout le pays. Leur défi consiste à produire des rendus réalistes de leurs et concours afin de convaincre un client, décrocher un marché ou commercialiser un produit immobilier. Nous avons aidé plusieurs architectes et professionnels à améliorer l''expérience visuelle de leurs clients à l’aide de nos….

La mission couvre typiquement les volets étude, accompagnement : 02 , 04 studio, 05 , conception générale de l''architecture. Impair studio intervient à Rabat, pour particuliers, promoteurs, entreprises et architectes / bureaux d''études, en mission nationale et internationale. Le tarif est établi sur devis, selon l''échelle et les phases confiées. Un accompagnement à distance est également possible.', 'Architecture / Ingénierie', 'https://www.impairstudio.com/images/og-default.jpg', '["https://www.impairstudio.com/uploads/lgc-libreville/1a1e59f3056d6310.webp", "https://www.impairstudio.com/uploads/renaissance/7a71a8693929a9a8.webp", "https://www.impairstudio.com/images/work/les-villas-danfa.webp", "https://www.impairstudio.com/images/work/sntl-agbaa.webp", "https://cdn.prod.website-files.com/66f14e2f3261dd914bfee34c/69ffa2049a7708f6fbc694c0_66f344666e390892e9e7fddf_5.webp", "https://www.impairstudio.com/images/frame-animation.webp", "https://www.impairstudio.com/images/frame-rendering.webp", "https://www.impairstudio.com/images/frame-interactive.webp"]'::jsonb, '["Étude", "Accompagnement"]'::jsonb, '["02 services", "04 studio", "05 contact", "Conception générale de l''architecture", "Dossiers administratifs et permis", "Coordination des intervenants"]'::jsonb, '["Architecture d''intérieur et agencement", "Gestion de projet à distance (diaspora / investisseurs étrangers)"]'::jsonb, 'devis', NULL, NULL, 'villes', '["Rabat"]'::jsonb, NULL, FALSE, TRUE, '["Particuliers", "Promoteurs", "Entreprises", "Architectes / Bureaux d''études"]'::jsonb, NULL, '["International", "National"]'::jsonb);
INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions) VALUES ('29f1c19a-4698-5786-9301-f64501cda176'::uuid, '96a7c268-9d94-51c7-a1e1-8aff5ba8b7a1'::uuid, 'Pose d''aluminium — étude, fourniture et pose', 'ORCA LUM – Profil de société Secteur d’activité : Construction et menuiserie industrielle Sous-secteurs : Menuiserie aluminium : portes, fenêtres, façades, cloisons, volets, baies vitrées sur mesure Portes isothermes et solutions techniques pour hôpitaux, hôtels, industries agroalimentaires et chambres froides Fabrication et installation sur mesure avec service après-vente Solutions pour bâtiments commerciaux, industriels et résidentiels Description générale : Orca Lum est une entreprise marocaine spécialisée….

