INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions) VALUES ('5499d54f-5f15-519b-9ffb-f0908cbc3014'::uuid, 'bfeb4f57-d596-5589-93ec-fdf3c4089beb'::uuid, 'Climatisation et chauffage — installation et maintenance', 'ATLAS CONFORT ET SECURITE (ACS) est un spécialiste des lots techniques du bâtiment, offrant des solutions complètes en Climatisation et traitement de l''air, fluides ainsi qu’une expertise multi technique. Nous assurons la fourniture, l’installation et la maintenance de systèmes de climatisation, ventilation et désenfumage, réfrigération, plomberie, électricité et courants faibles, protection incendie et piscines. Grâce à notre savoir-faire, nous accompagnons nos clients avec des solutions sur mesure, garantissant….

La mission couvre typiquement les volets fourniture, accompagnement : climatisation, ventilation, réfrigération, chauffage. ATLAS CONFORT ET SECURITE intervient à Casablanca, pour entreprises, en mission nationale. Le tarif est établi sur devis, selon l''échelle et les phases confiées.', 'Matériaux & équipements', 'https://atlas-cs.ma/wp-content/uploads/2023/07/Atlas-Confort-et-securite-1-scaled.jpg', '["https://atlas-cs.ma/wp-content/uploads/2023/07/Atlas-Confort-et-securite-1280x854.jpg", "https://atlas-cs.ma/wp-content/uploads/2023/07/Atlas-Confort-et-securite-980x653.jpg", "http://ishtiaq.sandbox.etdevs.com/corporate/wp-content/uploads/sites/37/2021/12/corporate_09.jpeg", "https://atlas-cs.ma/wp-content/uploads/2023/07/Atlas-Confort-et-securite-scaled.jpg", "https://atlas-cs.ma/wp-content/uploads/2023/07/Atlas-Confort-et-securite-480x320.jpg"]'::jsonb, '["Fourniture", "Accompagnement"]'::jsonb, '["Climatisation", "Ventilation", "Réfrigération", "Chauffage", "Activité distribution", "Activité installation"]'::jsonb, '["Contrat d''entretien", "Étude énergétique"]'::jsonb, 'devis', NULL, NULL, 'villes', '["Casablanca"]'::jsonb, NULL, FALSE, FALSE, '["Entreprises"]'::jsonb, NULL, '["National"]'::jsonb);
