INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions) VALUES ('a3270e4a-68e4-57ef-adef-5878b6408448'::uuid, 'bbb752e3-4aae-50c0-abfa-30d7dc26836f'::uuid, 'Installation d''ascenseurs — offre clé en main', 'Mission de professionnels BTP portée par GMR ASCENSEURS, basé à N°16 RUE 525 BOUZAKARE INEZGANE. Gmr est votre garant et partenaire idéal dans le domaine d’installation des ascenseurs et des systèmes de mobilité complémentaires. Notre principe est clair, assurer une installation fluide alliant les meilleures technologies et l’excellence de l’execution. Au-delà de l’installation, nous visons à assurer un suivi rigoureux afin de préserver la qualité emblématique de notre société. Nous garantissons la sécurité, confort et praticité L’innovation est notre levier, et notre équipe de professionnels hautement….

La mission couvre typiquement les volets réalisation, accompagnement : local machine obligatoire (Perte de m² utiles), risque de fuites d''huile & odeurs en sous-sol, niveau sonore élevé & vibrations au démarrage, surconsommation énergétique. GMR ASCENSEURS intervient au Maroc, avec déplacement possible, pour propriétaires, promoteurs, entreprises et architectes / bureaux d''études, en mission nationale et internationale. Le tarif est établi sur devis, selon l''échelle et les phases confiées. Un accompagnement à distance est également possible.', 'Second œuvre / Finitions', 'https://gmrascenseurs.com/opengraph-image.jpg?d2793d3b9c963aa0', '[]'::jsonb, '["Réalisation", "Accompagnement"]'::jsonb, '["Local machine obligatoire (Perte de m² utiles)", "Risque de fuites d''huile & odeurs en sous-sol", "Niveau sonore élevé & vibrations au démarrage", "Surconsommation énergétique", "Maintenance fréquente & coûteuse", "Sans salle des machines (Intégration MRL en gaine)"]'::jsonb, '["Options sur devis", "Gestion de projet à distance (diaspora / investisseurs étrangers)"]'::jsonb, 'devis', NULL, NULL, 'maroc', '["Agadir", "Casablanca", "Dakhla", "El Jadida", "Essaouira", "Guelmim", "Laâyoune", "Marrakech"]'::jsonb, 'Maroc', TRUE, TRUE, '["Propriétaires", "Promoteurs", "Entreprises", "Architectes / Bureaux d''études"]'::jsonb, NULL, '["International", "National"]'::jsonb);
INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions) VALUES ('600b25f0-abf4-5af3-9f96-90aa00f82c81'::uuid, '67796985-0882-52ca-8ddf-f74af40dbb4e'::uuid, 'Installation électrique — offre clé en main', 'ISODEC est une entreprise spécialisée dans les travaux de rénovation et d’aménagement intérieur pour particuliers et professionnels. Forte de plus de 25 ans d’expérience dans le domaine, notre équipe réalise des clés en main : cloisons et faux plafonds, revêtements de sol, peinture, électricité, menuiserie aluminium et ouvrages métalliques. Nous nous engageons sur la qualité d’exécution, le respect des délais et des solutions durables adaptées à chaque client.

La mission couvre typiquement les volets fourniture, accompagnement : nos et voyez comment nous apportons créativité et expertise à chaque projet, aménagement & Finition d''Espaces, faux Plafonds en BA13, découvrir ce service →. ISODEC intervient à Casablanca, pour particuliers, propriétaires, entreprises et investisseurs, en mission nationale. Le tarif est établi sur devis, selon l''échelle et les phases confiées.', 'Second œuvre / Finitions', 'https://www.isodec.ma/assets/homeHeroImage-768.avif', '["https://www.isodec.ma/assets/homeHeroImage-375.avif", "https://www.isodec.ma/assets/homeHeroImage-1920.avif", "https://www.isodec.ma/assets/homeHeroImage-1024.avif", "https://www.isodec.ma/assets/homeHeroImage-1440.avif", "https://www.isodec.ma/assets/sky-1024.avif", "https://www.isodec.ma/assets/services/travaux-electriques-1000.avif", "https://www.isodec.ma/assets/services/cloisonnement-aluminium-500.avif", "https://www.isodec.ma/assets/services/travaux-electriques-1500.avif"]'::jsonb, '["Fourniture", "Accompagnement"]'::jsonb, '["Nos services et voyez comment nous apportons créativité et expertise à chaque projet", "Aménagement & Finition d''Espaces", "Faux Plafonds en BA13", "Découvrir ce service →", "Faux plafonds modulaires 600 x 600", "Isolation en cloisonnement BA13"]'::jsonb, '["Options sur devis"]'::jsonb, 'devis', NULL, NULL, 'villes', '["Casablanca"]'::jsonb, NULL, FALSE, FALSE, '["Particuliers", "Propriétaires", "Entreprises", "Investisseurs"]'::jsonb, NULL, '["National"]'::jsonb);
INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions) VALUES ('9aeb5ee7-d34e-5aa7-84b1-af6741850116'::uuid, '814c1bbf-a285-5d7c-8cbb-eb15829d1061'::uuid, 'Installation de revêtement mural — sur devis', 'Mission de professionnels BTP portée par Duo Design, basé à 13 avenue tan-tan quartier bourgogne. 1. Aménagement intérieur & mobilier sur mesure portes placards cuisines bibliothèques 2. Design intérieur, mobilier custom et habillage mural 3. Solutions d’aménagement et décoration professionnelle 4. Mobilier sur mesure et design d’espaces commerciaux 5. Architecture intérieure & ment clé en main.

