INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions) VALUES ('f1400bdb-ac97-58a1-ac40-f8e5be6d5c08'::uuid, 'ccdb95a3-8054-5a89-bc17-a279fbdb9c0a'::uuid, 'Matériel électrique — offre clé en main', 'Mission de fourniture de matériaux et solutions chantier portée par HILTI MAROC, basé à Indusparc | M09 | Chemin Tertiaire 1015 Casablanca 20400. Chez Hilti, nous concevons et fabriquons de l’outillage électroportatif, des consommables, logiciels et de pointe destinés aux professionnels de la construction dans le bâtiment et l’industrie.

