INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions) VALUES ('8747a63d-ccd2-5278-9b42-4ad65168000b'::uuid, 'abf301a9-f0e7-5260-bd8f-87c44fc160f0'::uuid, 'Automatisme — offre clé en main', 'Ledcom est une entreprise marocaine spécialisée dans la distribution et l’intégration de solutions d’automatismes, de contrôle d’accès et de systèmes de sécurité. Nous accompagnons les promoteurs immobiliers, industriels et acteurs du tertiaire dans la mise en place de solutions fiables et performantes, adaptées aux exigences techniques et aux normes en vigueur. Notre expertise couvre notamment : Motorisation de portails et portes industrielles Barrières levantes et gestion de parkings Motorisation de fenêtres et….

