INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions) VALUES ('3aeb0997-7c08-52ed-ba01-416f90a0cfea'::uuid, 'df690491-dc89-584b-8502-0f0877ed4810'::uuid, 'Maîtrise d''œuvre architecturale — conception et suivi', 'Mission de maîtrise d''œuvre architecturale portée par Youssef LAHKIM Architecture Studio, basé à 20, Rue Abou Maachar, 3ème étage, Appt N°10 Quartier des Hôpitaux, 20360 , Maroc. Nos honoraires sont fixés en toute transparence, à partir de 5 % du montant des travaux hors taxes, adaptés à la complexité de chaque projet. À YLA Studio, chaque mission est conçue comme un partenariat où vos ambitions rencontrent notre savoir-faire.

