INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions) VALUES ('c968e931-0ce5-548a-ae8c-84d85b57d321'::uuid, '4b0fe318-590d-5fba-a7a5-a092e9dfbdd3'::uuid, 'Fourniture de matériaux et solutions chantier', 'Mission de fourniture de matériaux et solutions chantier portée par TOP GRAD Equipement, basé à 8Angle Rue de Rome etRue de Varsovie 2 MARS CASANLANCA. Depuis sa création en 2003, forte de ses 23 ans d''expérience, TOP GRAD s''est imposée comme un acteur de référence sur le marché marocain de l''équipement pour la cuisine professionnelle, la restauration et les métiers de bouche. Grâce à une solide expertise terrain et à une parfaite connaissance des besoins des professionnels, TOP GRAD sélectionne et distribue des marques reconnues à l''échelle internationale. Elle offre ainsi des solutions fiables, innovantes et haut de gamme destinées aux chefs, restaurateurs,….

La mission couvre typiquement les volets fourniture, accompagnement : conseil produit adapté au chantier, devis et disponibilité stock, livraison / retrait, support technique commercial. TOP GRAD Equipement intervient à Casablanca, pour entreprises, en mission nationale et internationale. Le tarif est établi sur devis, selon l''échelle et les phases confiées. Un accompagnement à distance est également possible.', 'Matériaux & équipements', 'https://tachrone-profile-logos-pro.s3.eu-west-3.amazonaws.com/file-9d8ee83b-2c0e-4676-86fd-3b703c0586e6.png', '[]'::jsonb, '["Fourniture", "Accompagnement"]'::jsonb, '["Conseil produit adapté au chantier", "Devis et disponibilité stock", "Livraison / retrait", "Support technique commercial", "Devis et disponibilité", "Fourniture / livraison"]'::jsonb, '["Livraison chantier", "Accompagnement poseur", "Gamme décorative"]'::jsonb, 'devis', NULL, NULL, 'villes', '["Casablanca"]'::jsonb, NULL, FALSE, TRUE, '["Entreprises"]'::jsonb, NULL, '["International", "National"]'::jsonb);
INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions) VALUES ('c3f070d3-724e-5dbc-8dc4-22947e836131'::uuid, 'c710e082-9514-5841-a80f-bca5220eeaf2'::uuid, 'Isolation — solutions pour le bâtiment', 'Mission de isolation et étanchéité portée par ISODUR HOUSE, basé à zone ind. Aïn Atiq 12000 Témara - Maroc. ISODUR s’engage à fournir la meilleure isolation thermique et acoustique au Maroc, en faisant émerger une industrie locale de produits innovants qui valorise pleinement les compétences nationales. Nous sommes déterminés à accompagner et soutenir les nationaux de développement, positionnant ainsi le Maroc en tant que fournisseur majeur de matériaux innovants pour un continent africain en pleine expansion.

La mission couvre typiquement les volets étude, accompagnement : continuous Support, project Management, architectural Solutions, an array of resources. ISODUR HOUSE intervient à Témara, pour particuliers et entreprises, en mission nationale. Le tarif est établi sur devis, selon l''échelle et les phases confiées.', 'Matériaux & équipements', 'https://isodurhouse.com/wp-content/themes/twentytwentyfour/assets/images/tourist-and-building.webp', '["https://isodurhouse.com/wp-content/themes/twentytwentyfour/assets/images/windows.webp", "https://isodurhouse.com/wp-content/themes/twentytwentyfour/assets/images/building-exterior.webp"]'::jsonb, '["Étude", "Accompagnement"]'::jsonb, '["Continuous Support", "Project Management", "Architectural Solutions", "An array of resources", "Études Architect App", "Collaborate with fellow architects"]'::jsonb, '["Audit thermique"]'::jsonb, 'devis', NULL, NULL, 'villes', '["Témara"]'::jsonb, NULL, FALSE, FALSE, '["Particuliers", "Entreprises"]'::jsonb, NULL, '["National"]'::jsonb);
