INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions) VALUES ('cc65849e-6c18-59d3-9131-a045115d3a9e'::uuid, 'e706cb5b-4e6d-5ac2-8617-402a4e68c0b5'::uuid, 'Étanchéité — solutions pour le bâtiment', 'Mission de isolation et étanchéité portée par AFRIQUE ÉTANCHÉITÉ, basé à Av hassan 2 mohamedia. Depuis plus de 50 ans, AFRIQUE ÉTANCHÉITÉ s’impose comme l’un des pionniers africains dans le domaine de l’étanchéité bitumineuse. De notre première ligne de production à notre présence actuelle sur le marché marocain et africain, notre histoire est celle d’une entreprise qui a su conjuguer tradition industrielle et innovation technologique. Portés par notre symbole emblématique – le coq – nous avons bâti une réputation solide fondée sur la fiabilité, la qualité et un engagement constant auprès des professionnels….

La mission couvre typiquement les volets fourniture, accompagnement : trouver mon système d’étanchéité, fondation d’AFRIQUE ETANCHEITE et mise en service, de la première ligne de production d’étancheité bitumineuse, lancement de la marque emblématique COQ AFRICAIN,. AFRIQUE ÉTANCHÉITÉ intervient à Mohammedia, pour entreprises, en mission nationale et internationale. Le tarif est établi sur devis, selon l''échelle et les phases confiées.', 'Matériaux & équipements', 'https://afriqueetancheite.com/wp-content/uploads/2026/03/20260221_182430-1024x768.jpg', '["https://afriqueetancheite.com/wp-content/uploads/2026/03/20251027_192051-1024x768.jpg", "https://afriqueetancheite.com/wp-content/uploads/2026/03/20260207_132258-1024x768.jpg", "https://afriqueetancheite.com/wp-content/uploads/2026/03/20250705_100942-1024x768.jpg", "https://afriqueetancheite.com/wp-content/uploads/2026/03/20260221_182430-scaled.jpg", "https://afriqueetancheite.com/wp-content/uploads/2026/03/20251027_192051-scaled.jpg", "https://afriqueetancheite.com/wp-content/uploads/2026/05/projet-1.jpg", "https://afriqueetancheite.com/wp-content/uploads/2026/03/20250705_100942-scaled.jpg", "https://afriqueetancheite.com/wp-content/uploads/2026/05/projet-2-1.jpg"]'::jsonb, '["Fourniture", "Accompagnement"]'::jsonb, '["Trouver mon système d’étanchéité", "Fondation d’AFRIQUE ETANCHEITE et mise en service", "De la première ligne de production d’étancheité bitumineuse", "Lancement de la marque emblématique COQ AFRICAIN,", "Symbole de robustesse et d’identité locale", "Installation d’une ligne de production dédiée au"]'::jsonb, '["Audit thermique"]'::jsonb, 'devis', NULL, NULL, 'villes', '["Mohammedia"]'::jsonb, NULL, FALSE, FALSE, '["Entreprises"]'::jsonb, NULL, '["International", "National"]'::jsonb);
