INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions) VALUES ('e74715e6-c465-5671-8480-625a17ce6703'::uuid, 'f4f55046-79f7-5b56-b32d-e42d32873858'::uuid, 'Laboratoire — offre clé en main', 'Mission de maîtrise d''œuvre architecturale portée par LABORATOIRE CIBTP, basé à BLOC E N°75 AV TAMRI HAY AGDAL AIT MELLOUL - INEZGANE. CIBTP est un Laboratoire du Centre d’Ingénierie du BTP spécialisé dans les études, les essais et le contrôle dans les domaines de la géotechnique des sols, des matériaux de construction, de l''ingénierie du bâtiment, du génie civil, de la géologie et de l''expertise.

La mission couvre typiquement les volets étude, accompagnement : eXPERTISE | QUALITÉ | CONFIANCE, cENTRE D’INGÉNIERIE DU BTP, expertise Technique, à PROPOS DE CIBTP. LABORATOIRE CIBTP intervient dans plusieurs villes (Agadir, Béni Mellal, Casablanca…), avec déplacement possible, pour particuliers et collectivités, en mission nationale. Le tarif est établi sur devis, selon l''échelle et les phases confiées.', 'Architecture / Ingénierie', 'https://cibtp.ma/wp-content/uploads/2021/10/repair-portfolio-1.jpg', '["https://cibtp.ma/wp-content/uploads/2021/10/repair-portfolio-6.jpg", "https://cibtp.ma/wp-content/uploads/2021/10/repair-portfolio-5.jpg", "https://cibtp.ma/wp-content/uploads/2021/10/repair-timeline-4.jpg", "https://cibtp.ma/wp-content/uploads/2021/10/repair-portfolio-3.jpg", "https://cibtp.ma/wp-content/uploads/2021/10/repair-timeline-3.jpg", "https://cibtp.ma/wp-content/uploads/2021/10/repair-portfolio-2.jpg", "https://cibtp.ma/wp-content/uploads/2021/10/repair-portfolio-4.jpg", "https://cibtp.ma/wp-content/uploads/2021/10/repair-timeline-2.jpg"]'::jsonb, '["Étude", "Accompagnement"]'::jsonb, '["EXPERTISE", "QUALITÉ", "CONFIANCE", "CENTRE D’INGÉNIERIE DU BTP", "Expertise Technique", "À PROPOS DE CIBTP", "Votre partenaire technique pour des ouvrages fiables et durables", "NOS SERVICES"]'::jsonb, '["Architecture d''intérieur et agencement"]'::jsonb, 'devis', NULL, NULL, 'villes', '["Agadir", "Béni Mellal", "Casablanca", "Guelmim", "Laâyoune", "Marrakech", "Ouarzazate"]'::jsonb, NULL, TRUE, FALSE, '["Particuliers", "Collectivités"]'::jsonb, NULL, '["National"]'::jsonb);
INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions) VALUES ('68ea41fe-0019-5fb7-968c-2eec1a3dbbb3'::uuid, 'c2cc9996-e951-5dd6-97d5-a42a1b3adf2d'::uuid, 'Étanchéité — solutions pour le bâtiment', 'PARM fabrique et distribue exclusivement les produits du groupe ARDEX des solutions techniques certifiées pour la pose de carrelage / la réparation structurelle du béton, l''étanchéité et le cuvelage, et les revêtements de sol industriels. La gamme PARM-ADER complète l''offre du groupe allemand ARDEX, dont nous sommes le représentant officiel et exclusif au Maroc — deux expertises réunies, conformes aux normes européennes.

La mission couvre typiquement les volets réalisation, accompagnement : discuter d''un ouvrage Voir nos domaines, nos domaines d''intervention, cinq domaines de solutions certifiées, étanchéité & cuvelage. PARM intervient dans plusieurs villes (Agadir, Casablanca, Dakhla…), avec déplacement possible, pour entreprises, en mission nationale et internationale. Le tarif est établi sur devis, selon l''échelle et les phases confiées.', 'Matériaux & équipements', 'https://parm-ardex.ma/og-parm.jpg', '[]'::jsonb, '["Réalisation", "Accompagnement"]'::jsonb, '["Discuter d''un ouvrage Voir nos domaines", "Nos domaines d''intervention", "Cinq domaines de solutions certifiées", "Étanchéité & cuvelage", "EN 1504-2 · ETAG 005 Voir la page →", "Pose de carrelage"]'::jsonb, '["Audit thermique"]'::jsonb, 'devis', NULL, NULL, 'villes', '["Agadir", "Casablanca", "Dakhla", "Laâyoune", "Marrakech", "Rabat"]'::jsonb, NULL, TRUE, FALSE, '["Entreprises"]'::jsonb, NULL, '["International", "National"]'::jsonb);
INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions) VALUES ('5e18eab7-8742-57d7-be11-aaae68823500'::uuid, '718fbd28-1b65-53ff-9eda-3ae85a360654'::uuid, 'Ferronnerie / Métallurgie — offre clé en main', 'Mission de professionnels BTP portée par CAP FER, basé à 63 Nouveau Souk Korea, Route Mediouna, Casablanca. Tubes carres, rectangulaires, ronds et galvanises pour serrurerie, ossatures, garde-corps et ment. Carres Rectangulaires Ronds Galvanises 100 REFERENCES.

La mission couvre typiquement les volets accompagnement : catalogue Poutrelles, poutrelles IPN, poutrelles UPN, tubes carrés. CAP FER intervient à Casablanca, pour particuliers et entreprises, en mission nationale. Le tarif est établi sur devis, selon l''échelle et les phases confiées. Un accompagnement à distance est également possible.', 'Second œuvre / Finitions', 'https://www.capfer.net/web/image/6086/capfer-cat-tole-galvanisee-20260520.png', '["https://www.capfer.net/web/image/6090/capfer-cat-tubes-carres-rectangulaires-20260520.png", "https://www.capfer.net/web/image/6096/capfer-cat-accessoires-20260520.png", "https://www.capfer.net/web/image/6084/capfer-cat-ipn-20260520.png", "https://www.capfer.net/web/image/6082/capfer-cat-fer-plat-lamines-20260520.png"]'::jsonb, '["Accompagnement"]'::jsonb, '["Catalogue Poutrelles", "Poutrelles IPN", "Poutrelles UPN", "Tubes carrés", "Tubes rectangulaires", "Tubes ronds"]'::jsonb, '["Options sur devis", "Gestion de projet à distance (diaspora / investisseurs étrangers)"]'::jsonb, 'devis', NULL, NULL, 'villes', '["Casablanca"]'::jsonb, NULL, FALSE, TRUE, '["Particuliers", "Entreprises"]'::jsonb, NULL, '["National"]'::jsonb);
INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions) VALUES ('cdfbdc3b-0bf3-59d9-a8c0-ba3576c178a8'::uuid, '7c6a8733-667f-505c-9316-a04fa686c38c'::uuid, 'Pierre naturelle — offre clé en main', 'Mission de fourniture de matériaux et solutions chantier portée par l''étanchiéte du casa nord, basé à route moulay thami hart el hamri dghoughat dar bouazza. Etanchéité du Casa nord Chaleur et élégance, notre passion dans chaque foyer. Des poêles à bois aux cheminées suspendues, des accessoires raffinés aux tuiles impeccables, découvrez l''art du confort chez nous. De la chaleur à l''esthétique, du foyer à la toiture, notre expertise réchauffe votre espace avec style et qualité.

La mission couvre typiquement les volets fourniture, accompagnement : nos spéciaux, cheminées à bois, carrelage Pierre de Bali, complété récemment. l''étanchiéte du casa nord intervient à Casablanca, pour particuliers, entreprises et architectes / bureaux d''études, en mission nationale. Le tarif est établi sur devis, selon l''échelle et les phases confiées.', 'Matériaux & équipements', 'https://www.ecn-cheminee-maroc.com/wp-content/uploads/2022/09/301869567_459083989275108_3995535113489731440_n-768x768.jpg', '["https://www.ecn-cheminee-maroc.com/wp-content/uploads/2019/02/301869567_459083989275108_3995535113489731440_n-740x556.jpg", "https://www.ecn-cheminee-maroc.com/wp-content/uploads/2019/02/293693912_577147240684280_8775411094353206290_n-768x576.jpg", "https://www.ecn-cheminee-maroc.com/wp-content/uploads/2019/02/293693912_577147240684280_8775411094353206290_n-740x556.jpg", "https://www.ecn-cheminee-maroc.com/wp-content/uploads/2022/09/293693912_577147240684280_8775411094353206290_n-600x600.jpg", "https://www.ecn-cheminee-maroc.com/wp-content/uploads/2022/09/301860617_366272922370516_1460360409765331258_n.jpg", "https://www.ecn-cheminee-maroc.com/wp-content/uploads/2022/09/301855553_483784223191205_6933432315836619623_n-300x300.jpg", "https://www.ecn-cheminee-maroc.com/wp-content/uploads/2019/02/293693912_577147240684280_8775411094353206290_n-300x225.jpg", "https://www.ecn-cheminee-maroc.com/wp-content/uploads/2019/02/293693912_577147240684280_8775411094353206290_n.jpg"]'::jsonb, '["Fourniture", "Accompagnement"]'::jsonb, '["Nos services spéciaux", "Cheminées à bois", "Carrelage Pierre de Bali", "Complété récemment", "Nos derniers projets", "Togel online"]'::jsonb, '["Livraison chantier", "Accompagnement poseur", "Gamme décorative"]'::jsonb, 'devis', NULL, NULL, 'villes', '["Casablanca"]'::jsonb, NULL, FALSE, FALSE, '["Particuliers", "Entreprises", "Architectes / Bureaux d''études"]'::jsonb, NULL, '["National"]'::jsonb);

